<?php
namespace App\Jobs;
use App\Contracts\SmsGateway;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Queue\Queueable;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\DB;use Throwable;
class SendQueuedSms implements ShouldQueue{use Queueable;public int $tries=3;public function __construct(public int $smsLogId){}public function handle(SmsGateway $gateway):void{$log=DB::table('SmsLogs')->where('SmsLogId',$this->smsLogId)->first();if(!$log||!in_array($log->Status,['Queued','Retrying'],true))return;$settings=DB::table('SmsSettings')->where('TenantId',$log->TenantId)->where('IsActive',true)->first();$config=$settings?(array)$settings:[];if($settings?->EncryptedCredentials)$config['ApiKey']=Crypt::decryptString($settings->EncryptedCredentials);$result=$gateway->send($log->RecipientPhone,$log->MessageBody,$config);DB::table('SmsLogs')->where('SmsLogId',$this->smsLogId)->update(['Status'=>'Sent','Attempts'=>DB::raw('Attempts + 1'),'ProviderMessageId'=>$result['provider_id'],'ProviderResponse'=>$result['response'],'SentAt'=>now()]);}public function failed(Throwable $error):void{DB::table('SmsLogs')->where('SmsLogId',$this->smsLogId)->update(['Status'=>'Failed','Attempts'=>DB::raw('Attempts + 1'),'ProviderResponse'=>mb_substr($error->getMessage(),0,1000),'FailedAt'=>now()]);}}
